-- NEW LOCAL disposable database ONLY. Never execute against Supabase.
CREATE TABLE profiles(id uuid PRIMARY KEY,role text);
CREATE TABLE drivers(id uuid PRIMARY KEY,profile_id uuid);
CREATE TABLE trucks(id uuid PRIMARY KEY,plate_number text);
CREATE TABLE trips(id uuid PRIMARY KEY,status text,archived_at timestamptz,dispatch_number text);
CREATE TABLE trip_truck_assignments(id uuid PRIMARY KEY,trip_id uuid REFERENCES trips,driver_id uuid REFERENCES drivers,truck_id uuid REFERENCES trucks,unassigned_at timestamptz,collaboration_version bigint DEFAULT 0);
CREATE TABLE customer_stores(id uuid PRIMARY KEY,name text,latitude numeric,longitude numeric);
CREATE TABLE trip_stops(id uuid PRIMARY KEY,trip_id uuid REFERENCES trips(id),store_id uuid REFERENCES customer_stores(id),stop_sequence integer,delivery_status text,archived_at timestamptz);
